<script setup lang="ts">
import {onMounted,ref} from "vue";
import {apiGet,apiPatch,apiPost,getApiErrorMessage} from "../lib/api";
import {useSessionStore} from "../stores/session";
import {useToastStore} from "../stores/toasts";
interface OtStatus{id:number;name:string;color:string;sort_order:number;active:boolean;is_initial:boolean;is_final:boolean;marks_quoted:boolean;marks_awaiting_quote_approval:boolean;marks_repair:boolean;marks_waiting_parts:boolean;marks_completed:boolean;notify_whatsapp:boolean;notify_email:boolean;notifications_active:boolean;notification_template:string|null;notification_email_subject:string|null;marks_delivered:boolean}
const session=useSessionStore(),toast=useToastStore(),statuses=ref<OtStatus[]>([]),loading=ref(false),showNew=ref(false);
type FlagKey="is_initial"|"is_final"|"marks_quoted"|"marks_awaiting_quote_approval"|"marks_repair"|"marks_waiting_parts"|"marks_completed"|"marks_delivered";
const FLAGS:{key:FlagKey;label:string}[]=[{key:"is_initial",label:"Inicial"},{key:"is_final",label:"Final (bloquea la OT)"},{key:"marks_quoted",label:"Presupuesto generado"},{key:"marks_awaiting_quote_approval",label:"Espera aprobación"},{key:"marks_repair",label:"En reparación"},{key:"marks_waiting_parts",label:"Espera repuesto"},{key:"marks_completed",label:"Finaliza trabajo"},{key:"marks_delivered",label:"Entrega equipo"}];
function flagsSummary(st:OtStatus){const on=FLAGS.filter(f=>st[f.key]).map(f=>f.label);return on.length?on.join(" · "):"Sin marcas"}
function notifSummary(st:OtStatus){if(!st.notifications_active)return "Sin aviso";const c=[st.notify_whatsapp&&"WhatsApp",st.notify_email&&"Email"].filter(Boolean);return c.length?c.join(" · "):"Sin canal elegido"}
const fresh=()=>({name:"",color:"#3B82F6",sort_order:90,active:true,is_initial:false,is_final:false,marks_quoted:false,marks_awaiting_quote_approval:false,marks_repair:false,marks_waiting_parts:false,marks_completed:false,notify_whatsapp:false,notify_email:false,notifications_active:true,notification_template:null,notification_email_subject:null,marks_delivered:false});const newStatus=ref(fresh());
const saved=ref<Record<number,string>>({});function snapshot(st:OtStatus){return JSON.stringify(st)}function isDirty(st:OtStatus){return saved.value[st.id]!==snapshot(st)}async function load(){loading.value=true;try{statuses.value=await apiGet<OtStatus[]>("/work-orders/statuses");for(const st of statuses.value){saved.value[st.id]=snapshot(st)}}catch(e){toast.push(getApiErrorMessage(e),"error")}finally{loading.value=false}}async function save(st:OtStatus){try{await apiPatch("/work-orders/statuses/"+st.id,st);saved.value[st.id]=snapshot(st);await load();toast.push("Estado guardado","success")}catch(e){toast.push(getApiErrorMessage(e),"error")}}
async function create(){try{await apiPost("/work-orders/statuses",newStatus.value);showNew.value=false;newStatus.value=fresh();await load();toast.push("Estado creado","success")}catch(e){toast.push(getApiErrorMessage(e),"error")}}
const templateVariables=ref<string[]>([]);async function loadVariables(){try{const r=await apiGet<{variables:string[]}>("/work-orders/notifications/variables");templateVariables.value=r.variables}catch(_){templateVariables.value=["cliente","numero_ot","equipo","estado"]}}onMounted(async()=>{await load();await loadVariables()});
</script>
<template><div class="card"><div class="flex flex--between heading"><div><h2>Estados de órdenes de trabajo</h2><p class="text-secondary">Flujo propio de {{session.activeCompany?.name}}. El color de cada estado se ve en su etiqueta, en el listado y en el detalle de las OT.</p></div><button class="btn btn--primary desktop-primary-action" @click="showNew=true">+ Nuevo estado</button><button class="mobile-fab" aria-label="Nuevo estado" @click="showNew=true">+<span>Estado</span></button></div><div v-if="loading" class="text-muted">Cargando estados…</div><div v-else class="status-admin"><div v-for="st in statuses" :key="st.id" class="row"><div class="row__main"><input v-model="st.color" class="color" type="color" :aria-label="'Color de '+st.name"><div class="field name"><label>Nombre</label><input v-model="st.name"></div><div class="field order"><label>Orden</label><input v-model.number="st.sort_order" type="number" min="0"></div><label class="check"><input v-model="st.active" type="checkbox"> Activo</label><button class="btn btn--sm" :class="isDirty(st)?'btn--primary':'btn--ghost'" :disabled="!isDirty(st)" @click="save(st)">{{isDirty(st)?"Guardar cambios":"Guardado"}}</button></div><details class="row__more"><summary>Qué hace este estado <span class="text-muted">{{flagsSummary(st)}}</span></summary><div class="flags-inline"><label v-for="f in FLAGS" :key="f.key" class="check"><input v-model="st[f.key]" type="checkbox"> {{f.label}}</label></div></details><details class="row__more"><summary>Aviso al cliente <span class="text-muted">{{notifSummary(st)}}</span></summary><div class="notif-config"><label class="check"><input v-model="st.notifications_active" type="checkbox"> Avisos al cliente</label><label class="check"><input v-model="st.notify_whatsapp" type="checkbox" :disabled="!st.notifications_active"> WhatsApp</label><label class="check"><input v-model="st.notify_email" type="checkbox" :disabled="!st.notifications_active"> Email</label><div class="field notif-template"><label>Mensaje</label><textarea v-model="st.notification_template" rows="2" :disabled="!st.notifications_active" placeholder="Hola {{cliente}}, tu OT N° {{numero_ot}} pasó a {{estado}}."></textarea></div><div class="field notif-template"><label>Asunto del email</label><input v-model="st.notification_email_subject" :disabled="!st.notifications_active || !st.notify_email" placeholder="Tu orden de trabajo {{numero_ot}}"></div><p v-if="st.notifications_active && (st.notify_whatsapp || st.notify_email)" class="notif-hint">Variables: {{ templateVariables.join(", ") }}</p></div></details></div></div><p class="text-muted note">“Presupuesto generado” identifica el estado al que pasa automáticamente la OT al emitir un presupuesto. “Finaliza trabajo” registra la finalización técnica. “Entrega equipo” registra la entrega real al cliente. <strong>“Espera repuesto”</strong> marca las OT frenadas por un repuesto: es lo que cuenta el panel “Requieren atención”, así que el nombre del estado puede ser el que quieras. Un mismo flag puede estar activo en un solo estado: al activarlo en uno nuevo se desactiva en el anterior. <strong>“Final”</strong> marca el cierre del ciclo: cuando la OT llega a él, el ciclo se cierra y no se puede cambiar de estado, ni generar diagnóstico, presupuesto, enviarlo, decidirlo, reabrir el diagnóstico ni modificar la fecha de entrega prevista.</p></div><div v-if="showNew" class="modal-backdrop"><div class="modal card status-modal"><div class="flex flex--between"><h2>Nuevo estado de OT</h2><button class="btn btn--ghost" @click="showNew=false">×</button></div><div class="field"><label>Nombre *</label><input v-model="newStatus.name" autofocus></div><div class="field__row"><div class="field"><label>Color</label><input v-model="newStatus.color" class="color color--large" type="color"></div><div class="field"><label>Orden</label><input v-model.number="newStatus.sort_order" type="number" min="0"></div></div><div class="flags"><label class="check"><input v-model="newStatus.active" type="checkbox"> Activo</label><label v-for="f in FLAGS" :key="f.key" class="check"><input v-model="newStatus[f.key]" type="checkbox"> {{f.label}}</label></div><div class="flex flex--between" style="margin-top:20px"><button class="btn btn--ghost" @click="showNew=false">Cancelar</button><button class="btn btn--primary" :disabled="!newStatus.name.trim()" @click="create">Crear estado</button></div></div></div></template>
<style scoped>.heading{align-items:flex-start;gap:16px}.heading h2{margin:0 0 6px}.status-admin{display:flex;flex-direction:column;margin-top:18px}/* Flex con wrap: con once checks por estado, una grilla de columnas fijas se desborda del card y deja el campo de asunto del email fuera de la pantalla. */.row{display:flex;flex-direction:column;gap:8px;margin:6px 0;padding:12px;border:1px solid var(--color-border);border-radius:12px;background:var(--color-surface)}.row__main{display:flex;flex-wrap:wrap;gap:10px 12px;align-items:end}.row__more summary{cursor:pointer;font-size:13px;font-weight:600;padding:4px 0}.row__more summary .text-muted{font-weight:400;margin-left:6px}.flags-inline{display:flex;flex-wrap:wrap;gap:4px 14px;padding:4px 0 2px}.color{width:52px;height:40px;padding:2px;border-radius:9px;cursor:pointer;flex:none}.name{flex:1 1 200px;min-width:0}.order{flex:0 0 80px}.name,.order{margin:0}.check{display:flex;align-items:center;gap:6px;min-height:40px;white-space:nowrap;font-size:13px}.notif-config{width:100%;display:flex;flex-wrap:wrap;gap:10px 12px;align-items:end;padding:4px 0 2px}.notif-template{flex:1 1 260px;min-width:0;margin:0}.notif-template textarea{resize:vertical;min-height:48px}.notif-hint{width:100%;margin:0;font-size:11px;color:var(--text-muted,#8290a5);word-break:break-word}.note{margin:16px 0 0}.modal-backdrop{position:fixed;inset:0;z-index:140;background:rgba(2,6,23,.72);display:grid;place-items:center;padding:20px}.status-modal{width:min(620px,100%)}.flags{display:flex;gap:18px;flex-wrap:wrap;margin-top:12px}@media(max-width:600px){.check{white-space:normal;min-height:44px}.heading{padding-bottom:2px}.status-modal{max-height:92dvh;overflow:auto}.flags{display:grid;grid-template-columns:1fr}.flags .check{padding:8px 0}}</style>